import {test} from 'node:test';
import assert from 'node:assert/strict';
import {modelRunSummary, modelTables, modelTableID, modelRunNotice} from '../config_web/model-run.mjs';

// The export a Grok preview produces: a comment header, then [model.*] tables.
const preview = `# Paste into ~/.grok/config.toml
# Generated by: llm-proxy --config FILE grok-models
# Endpoint: http://127.0.0.1:8890/v1

[model."ais-glm-5-2"]
model = "ais-glm-5-2"
base_url = "http://127.0.0.1:8890/v1"
name = "ais-glm-5-2"
api_backend = "messages"

[model."ais-new-key"]
model = "ais-new-key"
base_url = "http://127.0.0.1:8890/v1"
`;

// The file's model run: the same id owned by another proxy, plus the user's own
// entries and the neighbours a TOML scan must not mistake for model tables.
const disk = `[models]
default_reasoning_effort = "high"

[model."grok-4.5"]
context_window = 300000

[model.ais-glm-5-2]
model = "claude-fable-5"
base_url = "http://127.0.0.1:15722/v1"
api_key = "PROXY_MANAGED"
name = "AIS - GLM-5.2"
api_backend = "messages"

[model.cc-deepseek-v4-flash]
model = "deepseek/deepseek-v4-flash"
base_url = "http://localhost:8892/v1"

[telemetry]
trace_upload = false
`;

test('modelTableID matches model tables only', () => {
  assert.equal(modelTableID('[model."ais-glm-5-2"]'), 'ais-glm-5-2');
  assert.equal(modelTableID('[model.cc-deepseek-v4-flash]'), 'cc-deepseek-v4-flash');
  assert.equal(modelTableID('[model.x.extra]'), 'x');
  // The neighbours a scan must exclude.
  assert.equal(modelTableID('[models]'), '');
  assert.equal(modelTableID('[model_providers.messages-gateway]'), '');
  assert.equal(modelTableID('[[marketplace.sources]]'), '');
  assert.equal(modelTableID('[[model.sources]]'), '');
  assert.equal(modelTableID('[telemetry]'), '');
});

test('modelTables reads bodies and skips non-model tables', () => {
  const tables = modelTables(disk);
  assert.deepEqual([...tables.keys()], ['grok-4.5', 'ais-glm-5-2', 'cc-deepseek-v4-flash']);
  assert.deepEqual(tables.get('grok-4.5'), ['context_window = 300000']);
  assert.match(tables.get('ais-glm-5-2').join('\n'), /claude-fable-5/);
});

test('modelRunSummary separates shared, new, and file-only ids', () => {
  const summary = modelRunSummary(preview, disk);
  assert.equal(summary.generated, 2);
  assert.equal(summary.onDisk, 3);
  assert.deepEqual(summary.shared, ['ais-glm-5-2']);
  assert.deepEqual(summary.previewOnly, ['ais-new-key']);
  assert.deepEqual(summary.fileOnly, ['grok-4.5', 'cc-deepseek-v4-flash']);
});

test('a shared id with a different body is reported as differing', () => {
  // The real collision: same id, different upstream model, different port.
  const summary = modelRunSummary(preview, disk);
  assert.deepEqual(summary.different, ['ais-glm-5-2']);
  assert.match(modelRunNotice(summary), /1 shared key differ/);
  assert.match(modelRunNotice(summary), /1 new/);
  assert.match(modelRunNotice(summary), /2 file-only/);
});

test('a shared id with an identical body is not reported as differing', () => {
  const same = `[model.x]\nmodel = "x"\n`;
  const summary = modelRunSummary(same, same);
  assert.deepEqual(summary.different, []);
  assert.deepEqual(summary.shared, ['x']);
  assert.equal(modelRunNotice(summary), '1 generated · 1 in file');
});

test('an empty comparison reports no changes', () => {
  const summary = modelRunSummary('', '');
  assert.deepEqual(summary, {generated: 0, onDisk: 0, shared: [], different: [], previewOnly: [], fileOnly: []});
  assert.equal(modelRunNotice(summary), '0 generated · 0 in file');
});
